use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Enemy {
    name: String,
    health: i32,
    attack: i32,
    is_boss: bool,
}

impl Enemy {
    fn new(name: &str, health: i32, attack: i32, is_boss: bool) -> Self {
        Enemy {
            name: name.to_string(),
            health,
            attack,
            is_boss,
        }
    }
}

fn main() {
    let enemies = vec![
        Enemy::new("Goblin", 30, 8, false),
        Enemy::new("Orc", 50, 12, false),
        Enemy::new("Skeleton", 25, 6, false),
        Enemy::new("Dragon", 200, 25, true),
        Enemy::new("Troll", 80, 18, false),
        Enemy::new("Boss", 150, 30, true),
    ];

    // ---- Chain: multiple operations ----

    // 1. Filter → Map → Collect
    let boss_names: Vec<String> = enemies
        .iter()
        .filter(|e| e.is_boss)
        .map(|e| e.name.clone())
        .collect();
    println!("Bosses: {:?}", boss_names);

    // 2. Filter → Map → Sum
    let total_boss_health: i32 = enemies
        .iter()
        .filter(|e| e.is_boss)
        .map(|e| e.health)
        .sum();
    println!("Total boss health: {}", total_boss_health);

    // 3. Map → Filter → Collect
    let strong_enemies: Vec<String> = enemies
        .iter()
        .map(|e| &e.name)
        .filter(|name| name.len() > 5)
        .map(|name| name.to_string())
        .collect();
    println!("Enemies with long names: {:?}", strong_enemies);

    // 4. Enumerate → Filter → Map
    let indexed: Vec<(usize, &str)> = enemies
        .iter()
        .enumerate()
        .filter(|(i, e)| e.is_boss)
        .map(|(i, e)| (i, e.name.as_str()))
        .collect();
    println!("Boss indices: {:?}", indexed);

    // 5. Take + Skip
    let middle: Vec<&Enemy> = enemies
        .iter()
        .skip(1)
        .take(3)
        .collect();
    println!("Middle enemies:");
    for e in &middle {
        println!("  {}", e.name);
    }

    // 6. Chain: combine two iterators
    let more_enemies = vec![
        Enemy::new("Golem", 100, 15, false),
        Enemy::new("Lich", 120, 22, true),
    ];

    let all_enemies: Vec<&Enemy> = enemies
        .iter()
        .chain(more_enemies.iter())
        .collect();
    println!("\nAll enemies count: {}", all_enemies.len());

    // 7. Complex chain with stats
    let stats = enemies
        .iter()
        .filter(|e| !e.is_boss)
        .fold((0, 0), |(count, total_health), e| {
            (count + 1, total_health + e.health)
        });
    println!("Non-boss enemies: {}, average health: {:.2}", stats.0, stats.1 as f64 / stats.0 as f64);

    // 8. Chain with map to create a new type
    #[derive(Debug)]
    struct EnemySummary {
        name: String,
        threat_level: String,
    }

    let summaries: Vec<EnemySummary> = enemies
        .iter()
        .map(|e| EnemySummary {
            name: e.name.clone(),
            threat_level: if e.is_boss { "BOSS" } else if e.attack > 15 { "HIGH" } else { "LOW" },
        })
        .collect();

    println!("\nEnemy summaries:");
    for s in &summaries {
        println!("  {}: {}", s.name, s.threat_level);
    }
}

